    /// Returns the raw CupertinoIcons.ttf font data for loading into the engine.
    ///
    /// **`Bundle.module` is deliberately not used**, and the fallback below is
    /// why the distinction is easy to miss: SwiftPM's generated accessor is a
    /// `static let` that calls `fatalError` when neither of its two candidates
    /// resolves, so merely REACHING it crashes — the search underneath never
    /// runs. Its second candidate is an absolute path into the build directory
    /// that produced the binary, so it resolves on the machine that built the
    /// app and nowhere else. See the long note in TerminalView's
    /// `_fontBundle`; this is the same bug one target over, and it would have
    /// crashed the moment the first one was fixed.
    public static func fontData() -> Data {
        var roots: [URL] = []
        if let resources = Bundle.main.resourceURL { roots.append(resources) }
        roots.append(Bundle.main.bundleURL)
        roots.append(Bundle.main.bundleURL.appendingPathComponent("Contents/Resources"))
        if let exe = Bundle.main.executableURL?.deletingLastPathComponent() {
            roots.append(exe)
        }
        // `.bundle` is the Darwin name and `.resources` the name SwiftPM uses
        // on Linux and Windows -- see the note in TerminalView's `_fontBundle`.
        // Searching one suffix silently yields an empty Data() here, which is
        // every icon in the app drawn as nothing.
        for root in roots {
            for suffix in ["bundle", "resources"] {
                let candidate = root
                    .appendingPathComponent("FlutterSwift_CupertinoIcons.\(suffix)")
                if let bundle = Bundle(url: candidate),
                   let url = bundle.url(forResource: "CupertinoIcons", withExtension: "ttf"),
                   let data = try? Data(contentsOf: url) {
                    return data
                }
            }
        }
        // Last resort: straight off disk beside the executable, for a layout
        // Bundle() refuses to open at all. The package prefix is
        // `FlutterSwift_`, matching the loop above -- this list said
        // `FlutterSwiftBridge_` for as long as it has existed, which is a
        // directory that is never produced, so it has never once returned data.
        let execPath = ProcessInfo.processInfo.arguments[0]
        let execDir = (execPath as NSString).deletingLastPathComponent
        var searchPaths: [String] = []
        for dir in [execDir, "\(execDir)/.."] {
            for suffix in ["bundle", "resources"] {
                searchPaths.append(
                    "\(dir)/FlutterSwift_CupertinoIcons.\(suffix)/CupertinoIcons.ttf")
            }
        }
        for path in searchPaths {
            if let data = try? Data(contentsOf: URL(fileURLWithPath: path)) {
                return data
            }
        }
        return Data()
    }

    /// Registers the CupertinoIcons.ttf font with the Flutter engine.
    ///
    /// Call from `initState()` or after engine is running. Uses the synchronous
    /// C++ bridge directly so no async/await is needed.
    @discardableResult
    public static func registerFont() -> Bool {
        guard !_registered else { return true }

        let data = fontData()
        guard !data.isEmpty else { return false }

        // Call the C++ bridge directly (synchronous, works after engine init)
        let success = data.withUnsafeBytes { (buffer: UnsafeRawBufferPointer) -> Bool in
            guard let base = buffer.baseAddress else { return false }
            let ptr = base.assumingMemoryBound(to: UInt8.self)
            return flutter.swift_bridge.LoadFontFromList(ptr, data.count, _kFontFamily)
        }

        if success {
            _registered = true
        }
        return success
    }

